async getIdentity(workspacePath: string): Promise<GitIdentity> {
      const resolution = await this.resolveRepository(workspacePath);
      if (!resolution.isGitAvailable || !resolution.isRepository) {
        return {
          userName: null,
          userEmail: null,
          nameSource: null,
          emailSource: null,
          scopeLabel: null,
        };
      }

      const [nameResult, emailResult] = await Promise.all([
        commandProvider.run({
          cwd: resolution.repoRoot,
          args: ["config", "--show-scope", "--show-origin", "--get", "user.name"],
          timeoutMs: DEFAULT_GIT_COMMAND_TIMEOUT_MS,
        }),
        commandProvider.run({
          cwd: resolution.repoRoot,
          args: ["config", "--show-scope", "--show-origin", "--get", "user.email"],
          timeoutMs: DEFAULT_GIT_COMMAND_TIMEOUT_MS,
        }),
      ]);

      const name = parseGitConfigValue(nameResult);
      const email = parseGitConfigValue(emailResult);
      return {
        userName: name.value,
        userEmail: email.value,
        nameSource: name.source,
        emailSource: email.source,
        scopeLabel: name.scope ?? email.scope ?? null,
      };
    }

export function parseGitConfigValue(result: GitCommandExecutionResult): {
  scope: string | null;
  source: string | null;
  value: string | null;
} {
  if (result.exitCode === 1) {
    return { scope: null, source: null, value: null };
  }

  ensureGitCommandSucceeded("git config", result);
  const line = result.stdout.replace(/\r?\n$/, "");
  const parts = line.split("\t");
  if (parts.length < 3) {
    return { scope: null, source: null, value: line || null };
  }

  return {
    scope: parts[0] ?? null,
    source: parts[1] ?? null,
    value: parts.slice(2).join("\t") || null,
  };
}
